--
-- Name: asignarubicacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asignarubicacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	SELECT gid INTO NEW.idbarrio
	FROM barrio
	WHERE ST_Intersects(NEW.geom,geom)
	LIMIT 1;
	
	SELECT id INTO NEW.idvereda
	FROM vereda
	WHERE ST_Intersects(NEW.geom,geom)
	LIMIT 1;
	RETURN NEW;
END;
$$;


--
-- Name: encontrar_barrio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encontrar_barrio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	SELECT b.gid
	INTO NEW.idbarrio
	FROM barrio b
	WHERE ST_Contains(b.geom, NEW.geom)
	LIMIT 1;
	RETURN NEW;
END;
$$;


--
-- Name: generar_codigo_incidente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_codigo_incidente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    tipo CHAR(2);
    fecha TEXT;
    hora TEXT;
    contador BIGINT;
    numero INT;
    bloque INT;
    letras TEXT;
BEGIN

    -- 🔹 1. Obtener inicial del tipo desde la tabla
    SELECT UPPER(SUBSTRING(nametipoincidente, 1, 2))
    INTO tipo
    FROM tipo_incidente
    WHERE idtipoincidente = NEW.idtipoincidente;
	
    -- 🔹 2. Usar LOS DATOS DEL INCIDENTE (no NOW)
    fecha := TO_CHAR(NEW.fechaincidente, 'DDMMYY');
    hora := TO_CHAR(NEW.horaincidente, 'HH24MI');

    -- 🔹 3. Secuencia global
    contador := NEXTVAL('seq_incidente_global');

    -- 🔹 4. Lógica de numeración
    bloque := (contador - 1) / 9999;
    numero := (contador - 1) % 9999 + 1;

    -- 🔹 5. Letras tipo Excel
    letras := numero_a_letras(bloque + 1);

    -- 🔹 6. Construcción final
    NEW.codigoincidente := tipo || fecha || hora || letras || LPAD(numero::TEXT, 4, '0');

    RETURN NEW;
END;
$$;


--
-- Name: numero_a_letras(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.numero_a_letras(n integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    resultado TEXT := '';
BEGIN
    WHILE n > 0 LOOP
        resultado := CHR((n - 1) % 26 + 65) || resultado;
        n := (n - 1) / 26;
    END LOOP;
    RETURN resultado;
END;
$$;


